AssistantMessageToolRequest(name='create', tool_call_id='toolu_vrtx_01JMURb8CaeLLS28oS2EK8uv', arguments={'file_text': ':root {
  --bg: #f6f7f9;
  --surface: #ffffff;
  --text: #0f172a;
  --text-muted: #475569;
  --border: #e2e8f0;
  --border-strong: #cbd5e1;
  --primary: #2563eb;
  --danger: #b91c1c;
  --danger-hover: #991b1b;
  --danger-bg: #fef2f2;
  --focus: #1d4ed8;
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.06);
  --shadow-lg: 0 20px 40px -12px rgba(15, 23, 42, 0.25);
  --radius: 10px;
  --radius-lg: 14px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }

a { color: var(--primary); }

.container {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 8px;
  top: -40px;
  background: var(--text);
  color: #fff;
  padding: 8px 12px;
  border-radius: 6px;
  text-decoration: none;
  z-index: 1000;
}
.skip-link:focus { top: 8px; }

/* Header */
.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding-block: 16px;
  flex-wrap: wrap;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  text-decoration: none;
  color: var(--text);
  font-size: 1.125rem;
}
.brand-mark {
  color: var(--primary);
  font-size: 1.25rem;
}
.primary-nav {
  list-style: none;
  display: flex;
  gap: 8px;
  margin: 0;
  padding: 0;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 12px;
  border-radius: 8px;
  color: var(--text-muted);
  text-decoration: none;
  font-weight: 500;
}
.primary-nav a:hover { background: var(--bg); color: var(--text); }
.primary-nav a[aria-current="page"] {
  color: var(--text);
  background: var(--bg);
}

/* Breadcrumb */
.breadcrumb { margin: 24px 0 16px; font-size: 0.9rem; }
.breadcrumb ol {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 0;
  margin: 0;
  color: var(--text-muted);
}
.breadcrumb li + li::before {
  content: "/";
  margin: 0 8px;
  color: var(--border-strong);
}
.breadcrumb a {
  color: var(--text-muted);
  text-decoration: none;
}
.breadcrumb a:hover { color: var(--text); text-decoration: underline; }
.breadcrumb [aria-current="page"] { color: var(--text); font-weight: 500; }

/* Preview layout */
.preview {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 24px;
  margin-bottom: 48px;
}
@media (max-width: 820px) {
  .preview { grid-template-columns: 1fr; }
}

.preview-figure {
  margin: 0;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}
.preview-figure img {
  aspect-ratio: 3 / 2;
  object-fit: cover;
  width: 100%;
}

.preview-info {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}
.preview-info h1 {
  margin: 0 0 16px;
  font-size: 1.5rem;
  letter-spacing: -0.01em;
}

.meta {
  margin: 0 0 24px;
  display: grid;
  gap: 12px;
}
.meta > div {
  display: grid;
  grid-template-columns: 90px 1fr;
  gap: 12px;
  font-size: 0.9rem;
}
.meta dt { color: var(--text-muted); margin: 0; }
.meta dd { margin: 0; color: var(--text); font-weight: 500; }

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

/* Buttons */
.btn {
  font: inherit;
  font-weight: 600;
  padding: 10px 16px;
  border-radius: var(--radius);
  border: 1px solid transparent;
  cursor: pointer;
  background: transparent;
  color: var(--text);
  transition: background-color 0.15s, border-color 0.15s, color 0.15s, box-shadow 0.15s;
  min-height: 40px;
}
.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}
.btn-secondary {
  background: var(--surface);
  border-color: var(--border-strong);
  color: var(--text);
}
.btn-secondary:hover { background: var(--bg); }
.btn-danger {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger);
}
.btn-danger:hover { background: var(--danger-hover); border-color: var(--danger-hover); }

/* Dialog */
.confirm-dialog {
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  max-width: 440px;
  width: calc(100% - 32px);
  background: var(--surface);
  color: var(--text);
  box-shadow: var(--shadow-lg);
}
.confirm-dialog::backdrop {
  background: rgba(15, 23, 42, 0.55);
  backdrop-filter: blur(2px);
}

.dialog-body {
  margin: 0;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.dialog-body h2 {
  margin: 0;
  font-size: 1.25rem;
  letter-spacing: -0.01em;
}
.dialog-body p {
  margin: 0;
  color: var(--text-muted);
}
.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 12px;
  flex-wrap: wrap;
}

/* Subtle open animation, but respect reduced motion */
@media (prefers-reduced-motion: no-preference) {
  .confirm-dialog[open] {
    animation: dialog-in 160ms ease-out;
  }
  @keyframes dialog-in {
    from { opacity: 0; transform: translateY(-4px) scale(0.98); }
    to   { opacity: 1; transform: none; }
  }
}

/* Visually hidden helper */
.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* Forced colors / high contrast support */
@media (forced-colors: active) {
  .btn { border: 1px solid ButtonBorder; }
  .btn-danger { background: Mark; color: MarkText; }
  .confirm-dialog { border: 1px solid CanvasText; }
}
