  const css = fs.readFileSync(path.join(__dirname, 'styles.css'), 'utf8');
  const htmlInlined = html.replace(
    /<link rel="stylesheet" href="styles.css"\s*\/?>/,
    `<style>${css}</style>`
  );

  const dom = new JSDOM(htmlInlined, {
    runScripts: 'dangerously',
    pretendToBeVisual: true,
    url: 'http://localhost/',
  });
  const { window } = dom;

  const proto = window.HTMLDialogElement
    ? window.HTMLDialogElement.prototype
    : window.HTMLElement.prototype;
  proto.showModal = function () { this.setAttribute('open', ''); };
  proto.show = function () { this.setAttribute('open', ''); };
  proto.close = function (v) {
    this.removeAttribute('open');
    this.returnValue = v || '';
    this.dispatchEvent(new window.Event('close'));
  };

  await new Promise(r => window.addEventListener('load', r));
  window.eval(axeSource);

  async function run(label) {
    const results = await window.axe.run(window.document, {
      resultTypes: ['violations'],
    });
    console.log(`\n=== ${label} ===`);
    console.log(`Violations: ${results.violations.length}`);
    for (const v of results.violations) {
      console.log(`- [${v.impact}] ${v.id}: ${v.help}`);
      for (const n of v.nodes) {
        console.log(`    target: ${n.target.join(' ')}`);
        if (n.failureSummary) console.log(`    why: ${n.failureSummary.replace(/\n/g, ' | ')}`);
      }
    }
    return results.violations.length;
  }

  let total = 0;
  total += await run('Initial state (dialog closed)');

  window.document.getElementById('delete-trigger').click();
  await new Promise(r => setTimeout(r, 50));
  total += await run('Dialog open');

  console.log(`\nTotal violations: ${total}`);
  process.exit(total === 0 ? 0 : 1);
})().catch(err => { console.error(err); process.exit(2); });

